function showExitRiskAssessment(){const overlay=document.getElementById('exit-risk-overlay');const hpRow=document.getElementById('exit-hp-row');const infoRow=document.getElementById('exit-info-row');const optionsEl=document.getElementById('exit-options');const currentHP=getCurrentHP();const maxHP=getMaxHP();const hpPct=getHPPercent();const distance=bfsDistanceToExit(S.playerCol,S.playerRow);const risk=calculateExitRisk(distance);const hpColor=hpPct>60?'#4caf50':hpPct>25?'#f97316':'#ef4444';hpRow.innerHTML=`<span>HP</span>`+`<div class="exit-hp-bar"><div class="exit-hp-fill" style="transform:scaleX(${Math.max(0.02, hpPct/100)});background:${hpColor}"></div></div>`+`<span>${currentHP}/${maxHP}</span>`;const distText=distance>=0?`${distance} turnos`:'???';const dangerLvl=S.dangerLevel||1;const estEnc=distance>0?Math.max(1,Math.round(distance*dangerLvl*0.04)):0;const encText=estEnc>0?`<span>~${estEnc} encontro${estEnc > 1 ? 's' : ''}</span>`:'';infoRow.innerHTML=`<span>${distText} até a saída</span>`+`<span style="color:${risk.color}">Risco: ${risk.label} (${risk.chance}%)</span>`+
encText;optionsEl.innerHTML='';addExitOption(optionsEl,'','Retornar à Cidade',distance>=0?`Jornada de ${distance} turnos, ${risk.chance}% risco`:'Rota desconhecida',risk.color,()=>{overlay.classList.remove('active');attemptReturnToCity(risk.chance);});const healItems=getHealingItems();if(healItems.length>0&&hpPct<100){const best=healItems[0];addExitOption(optionsEl,best.e||'',`Usar ${best.n} (${best.q}x)`,`Restaura ${best.h} HP`,'#4a8',()=>{overlay.classList.remove('active');useInventoryItemAnimated(best,(heal)=>{showTerrainToast(`${best.e || ''} +${heal} HP`,'ranger');setTimeout(()=>showExitRiskAssessment(),300);});});}
addExitOption(optionsEl,'','Continuar Explorando','Voltar ao mapa','#8a7a68',()=>{overlay.classList.remove('active');});overlay.classList.add('active');}
function addExitOption(container,icon,title,desc,color,onClick){const btn=document.createElement('button');btn.className='exit-option-btn';btn.innerHTML=`<span class="exit-option-icon">${icon}</span>`+`<div class="exit-option-info">`+`<div class="exit-option-title">${title}</div>`+`<div class="exit-option-desc" style="color:${color}">${desc}</div>`+`</div>`;btn.addEventListener('click',onClick);container.appendChild(btn);}
var CAMP_ATMOSPHERE={forest:['A fogueira crepita suavemente entre as arvores. O cheiro de musgo e terra umida preenche o ar.','Grilos cantam ao redor. A luz das chamas danca nas folhas, criando sombras hipnoticas.'],plains:['O vento da planicie sopra gentilmente. As estrelas brilham vastas acima de voce.','A grama alta sussurra ao redor. Um momento de paz na imensidao.'],desert:['O calor do dia finalmente cede. A noite do deserto traz um frio inesperado.','As dunas brilham prateadas sob a lua. O silencio e quase meditativo.'],snow:['A neve abafa todos os sons. Apenas o crepitar da fogueira quebra o silencio gelado.','Cristais de gelo brilham a luz das chamas como pequenos diamantes.'],swamp:['O ar pesado do pantano se mistura com a fumaca da fogueira. Luzes estranhas brilham ao longe.','Sapos coaxam na escuridao. A fogueira mantem as criaturas do pantano a distancia.'],mountain:['O vento uiva entre os picos. Daqui de cima, o mundo parece pequeno e distante.','A fogueira luta contra o vento da montanha. Cada rajada faz as chamas dancarem.'],volcanic:['O chao emana calor. Fissuras distantes brilham alaranjadas na escuridao.','O ar tremula com o calor. A fogueira parece quase desnecessaria neste lugar.'],cave:['Gotas de agua ecoam na escuridao da caverna. A fogueira projeta sombras imensas nas paredes.','Estalactites brilham a luz do fogo. Um refugio seguro nas profundezas.'],graveyard:['O silencio e denso entre as lapides. A fogueira e sua unica companhia neste lugar.','A nevoa se arrasta ao redor. Melhor descansar rapido e seguir em frente.'],};function showCampOverlay(){var overlay=document.getElementById('camp-overlay');var foodList=document.getElementById('camp-food-list');foodList.innerHTML='';var biome=S.biome||'forest';var pool=CAMP_ATMOSPHERE[biome]||CAMP_ATMOSPHERE.forest;var atmoText=pool[Math.floor(Math.random()*pool.length)];var atmoDiv=document.createElement('div');atmoDiv.style.cssText='text-align:center;font-size:12px;color:#a09484;font-style:italic;line-height:1.5;margin-bottom:8px;padding:0 8px';atmoDiv.textContent=atmoText;foodList.appendChild(atmoDiv);const maxHD=(S.charData&&S.charData.mhd)||1;const hdRemaining=Math.max(0,maxHD-(S._hdUsed||0));const canShortRest=hdRemaining>0;const hdType=(S.charData&&S.charData.hdt)||'1d8';const shortHeader=document.createElement('div');shortHeader.style.cssText='font-size:11px;color:#8a7a68;text-align:center;margin-bottom:4px';shortHeader.textContent=`\u2500\u2500 Descanso Curto (1 hora) \u2500\u2500 Dados de Vida: ${hdRemaining}/${maxHD}`;foodList.appendChild(shortHeader);if(!canShortRest){const noHD=document.createElement('div');noHD.style.cssText='text-align:center;color:#c44;font-size:12px;padding:8px;font-style:italic';noHD.textContent='Sem Dados de Vida restantes para descanso curto.';foodList.appendChild(noHD);}
const foodItems=getFoodItems();for(const food of foodItems){const btn=document.createElement('button');btn.className='camp-food-btn';const healText=food.h&&food.h!=='0'?` (+${food.h} HP)`:'';btn.innerHTML=`<span style="font-size:14px;color:#c4953a;font-weight:bold">${food.n ? food.n[0] : '•'}</span>`+`<div style="flex:1"><div style="font-weight:600">${food.n} (${food.q}x)</div>`+`<div style="font-size:11px;color:#8a7a68">Refeição${healText}</div></div>`;if(canShortRest){btn.addEventListener('click',()=>{overlay.classList.remove('active');doCampRest(food);});}else{btn.style.opacity='0.4';btn.style.pointerEvents='none';}
foodList.appendChild(btn);}
const noFoodBtn=document.createElement('button');noFoodBtn.className='camp-food-btn';noFoodBtn.innerHTML=`<span style="font-size:14px;color:#8a7a68;font-weight:bold">—</span>`+`<div style="flex:1"><div style="font-weight:600">Descansar sem comer</div>`+`<div style="font-size:11px;color:#8a7a68">Apenas ${hdType} + CON</div></div>`;if(canShortRest){noFoodBtn.addEventListener('click',()=>{overlay.classList.remove('active');doCampRest(null);});}else{noFoodBtn.style.opacity='0.4';noFoodBtn.style.pointerEvents='none';}
foodList.appendChild(noFoodBtn);const divider=document.createElement('div');divider.style.cssText='border-top:1px solid rgba(196,149,58,0.2);margin:8px 0;padding-top:4px;font-size:11px;color:#8a7a68;text-align:center';divider.textContent='\u2500\u2500 Descanso Longo (8 horas) \u2500\u2500';foodList.appendChild(divider);const weatherBonus=S.weather==='t'?15:S.weather==='r'?5:0;const ambushChance=20+((S._longRestCount||0)*15)+weatherBonus;const longRestBtn=document.createElement('button');longRestBtn.className='camp-food-btn';longRestBtn.style.borderColor='rgba(68,170,100,0.4)';let longDesc='Recupera todo HP, limpa condi\u00e7\u00f5es, -1 exaust\u00e3o';longDesc+=`<br>\u26a0\ufe0f Chance de emboscada: ${Math.min(ambushChance, 95)}%`;if((S._longRestCount||0)>=2)longDesc+='<br>\u26a0\ufe0f Perigo da regi\u00e3o j\u00e1 aumentou';longRestBtn.innerHTML=`<span style="font-size:14px;color:#4a8;font-weight:bold">\ud83c\udf19</span>`+`<div style="flex:1"><div style="font-weight:600;color:#6c8">Descanso Longo</div>`+`<div style="font-size:11px;color:#8a7a68">${longDesc}</div></div>`;longRestBtn.addEventListener('click',()=>{overlay.classList.remove('active');_startGuardWatch();});foodList.appendChild(longRestBtn);overlay.classList.add('active');if(typeof setCampfireActive==='function')setCampfireActive(true);}
function closeCampOverlay(){document.getElementById('camp-overlay').classList.remove('active');if(typeof setCampfireActive==='function')setCampfireActive(false);}
function doCampRest(food){const hdType=(S.charData&&S.charData.hdt)||'1d8';const hitDie=rollDiceFormula(hdType);const conMod=getAbilityMod('cn');const baseHeal=Math.max(1,hitDie+conMod);S._hdUsed=(S._hdUsed||0)+1;let foodBonus=0;let foodName='sem refeição';if(food){foodName=food.n;if(food.h&&food.h!=='0'){foodBonus=rollDiceFormula(food.h);}
useInventoryItem(food);}
const totalHeal=baseHeal+foodBonus;S.hpChange+=totalHeal;if(S.charData){const newHP=Math.min(S.charData.mh,S.charData.hp+S.hpChange);updateHP(newHP,S.charData.mh);}
logMoveEvent([{type:'camp',heal:totalHeal,food:foodName}]);updateRewards();if(typeof resetStepsWithoutRest==='function')resetStepsWithoutRest();saveState();if(typeof updateCampButtonHint==='function')updateCampButtonHint();let mpRecovered=0;if(S.charData&&S.charData.mm>0){const mpr=S.charData.mpr||'none';const maxMP=S.charData.mm;if(mpr==='full')mpRecovered=maxMP;else if(mpr==='half')mpRecovered=Math.ceil(maxMP/2);else if(mpr==='third')mpRecovered=Math.ceil(maxMP/3);if(mpRecovered>0){S.mpChange=(S.mpChange||0)+mpRecovered;saveState();}}
_showCampDiceRoll(hitDie,conMod,foodBonus,totalHeal,foodName,hdType,mpRecovered);}
var CAMPFIRE_STORIES={forest:['O crepitar da fogueira mistura-se ao canto dos grilos. Entre as \u00e1rvores, vaga-lumes dan\u00e7am como estrelas ca\u00eddas.','O vento sussurra entre os galhos antigos. Voc\u00ea jura ouvir uma melodia distante, quase como uma can\u00e7\u00e3o de ninar.','Uma coruja pia ao longe. A floresta \u00e9 escura, mas a fogueira \u00e9 quente. Por ora, voc\u00ea est\u00e1 seguro.','As chamas projetam sombras dan\u00e7antes nos troncos. Uma delas parece ter forma humana por um instante.',],plains:['O c\u00e9u noturno se abre vasto sobre a plan\u00edcie. Mais estrelas do que voc\u00ea jamais viu pontuam a escurid\u00e3o.','A brisa traz o cheiro de grama fresca. No horizonte, a lua cheia ilumina o caminho que voc\u00ea percorreu.','Os grilos cantam ao redor. A fogueira \u00e9 um ponto de luz solit\u00e1rio na vastid\u00e3o da plan\u00edcie.',],desert:['O calor do deserto finalmente cede. A noite traz um frio cortante que faz a fogueira parecer um tesouro.','As dunas brilham prateadas sob a lua. O sil\u00eancio do deserto \u00e9 t\u00e3o profundo que voc\u00ea ouve seu pr\u00f3prio cora\u00e7\u00e3o.','Uma estrela cadente risca o c\u00e9u. Os viajantes do deserto dizem que \u00e9 um bom pres\u00e1gio.',],snow:['A neve cai suavemente ao redor da fogueira, derretendo antes de tocar as chamas. Um manto branco cobre tudo.','O frio morde at\u00e9 os ossos, mas o calor da fogueira mant\u00e9m a escurid\u00e3o gelada \u00e0 dist\u00e2ncia.','Aurora boreal dan\u00e7a no c\u00e9u noturno. Cores que nenhum artista conseguiria reproduzir.',],swamp:['O p\u00e2ntano borbulha na escurid\u00e3o. Luzes estranhas flutuam entre as \u00e1rvores mortas.','O ar \u00e9 pesado e \u00famido. Sapos coaxam um coro desafinado que, de alguma forma, \u00e9 reconfortante.',],mountain:['Do alto, as luzes de aldeias distantes cintilam como velas. O vento uiva entre os picos rochosos.','A fogueira luta contra o vento da montanha. Cada rajada faz as chamas dan\u00e7arem furiosamente.',],volcanic:['O ch\u00e3o \u00e9 quente mesmo longe das fissuras. A fogueira quase parece desnecess\u00e1ria neste calor infernal.','Um brilho alaranjado pulsa no horizonte. A terra vive e respira aqui, inquieta sob seus p\u00e9s.',],cave:['Gotas de \u00e1gua ecoam na escurid\u00e3o da caverna. A fogueira projeta sombras imensas nas paredes de pedra.','Forma\u00e7\u00f5es de estalactites brilham \u00e0 luz do fogo, como j\u00f3ias incrustadas no teto.',],graveyard:['O sil\u00eancio \u00e9 denso. Nem os mortos fazem barulho aqui \u2014 ou talvez fa\u00e7am, e voc\u00ea prefere n\u00e3o ouvir.','A n\u00e9voa se arrasta entre as l\u00e1pides. A fogueira \u00e9 sua \u00fanica companhia neste lugar esquecido.',],_generic:['As chamas dan\u00e7am e crepitam. O calor \u00e9 reconfortante depois de um longo dia de viagem.','Voc\u00ea observa as brasas brilharem como pequenos s\u00f3is. Amanh\u00e3 ser\u00e1 um novo dia de aventura.','O cansa\u00e7o pesa sobre seus ombros, mas a fogueira aquece seu esp\u00edrito. Valdoria ainda guarda muitos segredos.','O sil\u00eancio da noite \u00e9 quebrado apenas pelo estalar da lenha. Momentos de paz s\u00e3o raros nesta terra.','Voc\u00ea pensa nos caminhos que ainda restam. Cada hex\u00e1gono pode esconder perigo ou tesouro \u2014 ou ambos.',]};function _getCampfireStory(){var biome=S.currentBiome||'_generic';var stories=CAMPFIRE_STORIES[biome]||CAMPFIRE_STORIES._generic;var pool=stories.concat(CAMPFIRE_STORIES._generic);return pool[Math.floor(Math.random()*pool.length)];}
function _startGuardWatch(){const wisMod=getAbilityMod('ws');const profInPerception=S.charData&&S.charData.sp&&S.charData.sp.includes('per');const profBonus=profInPerception?(S.charData.pb||2):0;const totalMod=wisMod+profBonus;const exhDis=(S.exhaustion||0)>=1;const mode=exhDis?'disadvantage':'normal';const{roll,r1,r2}=rollD20(mode);const total=roll+totalMod;const dangerDC=10+Math.floor((S.dangerLevel||1)*2);S._guardRoll=total;S._guardDC=dangerDC;S._guardSuccess=total>=dangerDC;S._campfireStory=_getCampfireStory();_showGuardOverlay(roll,r1,r2,mode,totalMod,profInPerception,dangerDC,total>=dangerDC);}
function _showGuardOverlay(roll,r1,r2,mode,totalMod,proficient,dc,success){const overlay=document.getElementById('check-overlay');const formulaEl=document.getElementById('check-formula');const resultEl=document.getElementById('check-result');const diceContainer=document.getElementById('dice3d-wrapper');const diceCanvas=document.getElementById('dice3d-canvas');if(!overlay){doLongRest();return;}
const sign=totalMod>=0?'+':'';const profText=proficient?' (proficiente)':'';const disText=mode==='disadvantage'?' <span style="color:#c44">(desvantagem)</span>':'';const narrations=['A fogueira se reduz a brasas. O silêncio da noite se instala...','Sons distantes ecoam pela escuridão. Você aguça os sentidos...','As horas passam lentamente. Cada sombra parece se mover...','O vento sussurra entre as árvores. Algo se move na escuridão...',];const narr=narrations[Math.floor(Math.random()*narrations.length)];formulaEl.innerHTML='<div style="font-size:13px;color:#c4953a;margin-bottom:6px">\u{1f6e1}\ufe0f Montando Guarda</div>'+'<div style="font-size:12px;color:#a09484;font-style:italic;margin-bottom:8px;line-height:1.5">'+narr+'</div>'+'<div style="font-size:11px;color:#8a7a68">Percep\u00e7\u00e3o (WIS)'+profText+disText+'</div>'+'<div style="font-size:11px;color:#8a7a68;margin-top:2px">DC '+dc+'</div>';resultEl.innerHTML='';const diceHTML=typeof buildDiceHTML==='function'?buildDiceHTML(r1,r2,mode):'';if(diceContainer)diceContainer.innerHTML=diceHTML;overlay.classList.add('active');const narrDelay=typeof calcReadTime==='function'?calcReadTime(narr,'narrative'):2500;setTimeout(function(){if(diceCanvas&&typeof Dice3D!=='undefined'){try{if(window._checkDice){window._checkDice.dispose();window._checkDice=null;}
if(typeof _dice3d!=='undefined'&&_dice3d){_dice3d.dispose();_dice3d=null;}
diceCanvas.style.display='block';diceCanvas.innerHTML='';window._checkDice=new Dice3D(diceCanvas,{size:120,dieType:'d20',duration:1200});window._checkDice.roll(roll,function(){if(window.vHaptic)vHaptic.medium();_showGuardResult(overlay,resultEl,diceCanvas,roll,sign,totalMod,dc,success);});}catch(e){console.warn('[EXPLORE] Guard dice error:',e);_showGuardResult(overlay,resultEl,diceCanvas,roll,sign,totalMod,dc,success);}}else{_showGuardResult(overlay,resultEl,diceCanvas,roll,sign,totalMod,dc,success);}},narrDelay);}
function _showGuardResult(overlay,resultEl,diceCanvas,roll,sign,totalMod,dc,success){const total=roll+totalMod;const successNarrs=['Seus olhos penetram a escuridão. Nada escapa à sua vigília.','Um galho estala ao longe. Você identifica: apenas um animal. A noite está segura.','A aurora desponta. Sua guarda foi impecável.',];const failNarrs=['O calor da fogueira e o cansaço vencem... seus olhos pesam...','Um som distante... ou foi imaginação? O sono chega antes da resposta.','As pálpebras cedem. Quando você acorda, horas se passaram.',];const postNarr=success?successNarrs[Math.floor(Math.random()*successNarrs.length)]:failNarrs[Math.floor(Math.random()*failNarrs.length)];if(success){resultEl.innerHTML='<div style="color:#6c8;font-size:16px;font-weight:700">\u2705 Vigilância Alerta</div>'+'<div style="font-size:12px;color:#8a7a68;margin-top:4px">'+roll+' '+sign+totalMod+' = '+total+' \u2265 DC '+dc+'</div>'+'<div style="font-size:12px;color:#a09484;font-style:italic;margin-top:8px;line-height:1.5">'+postNarr+'</div>';}else{resultEl.innerHTML='<div style="color:#c44;font-size:16px;font-weight:700">\u274c Guarda Falha</div>'+'<div style="font-size:12px;color:#8a7a68;margin-top:4px">'+roll+' '+sign+totalMod+' = '+total+' < DC '+dc+'</div>'+'<div style="font-size:12px;color:#a09484;font-style:italic;margin-top:8px;line-height:1.5">'+postNarr+'</div>';}
const readDelay=typeof calcReadTime==='function'?calcReadTime(postNarr+' Vigilância resultado','overlay'):3500;setTimeout(function(){overlay.classList.remove('active');if(diceCanvas)diceCanvas.style.display='none';if(window._checkDice){window._checkDice.dispose();window._checkDice=null;}
doLongRest();},readDelay+1000);}
function doLongRest(){S._longRestCount=(S._longRestCount||0)+1;if(S.charData){const maxHP=S.charData.mh||10;const currentHP=S.charData.hp+S.hpChange;const healed=maxHP-currentHP;if(healed>0)S.hpChange+=healed;updateHP(maxHP,maxHP);}
S.conditions=[];updateConditionHUD();if(S.charData&&S.charData.mm>0){const maxMP=S.charData.mm;const currentMP=(S.charData.mp||0)+(S.mpChange||0);const mpRecov=maxMP-currentMP;if(mpRecov>0)S.mpChange=(S.mpChange||0)+mpRecov;}
const maxHD=(S.charData&&S.charData.mhd)||1;const hdRecov=Math.max(1,Math.floor(maxHD/2));S._hdUsed=Math.max(0,(S._hdUsed||0)-hdRecov);const prevExhaustion=S.exhaustion;if(S.weather==='t'){if(typeof addExhaustion==='function')addExhaustion(1,'Tempestade durante descanso');}else if(typeof removeExhaustion==='function'&&S.exhaustion>0){removeExhaustion(1);}
if(typeof resetStepsWithoutRest==='function')resetStepsWithoutRest();S.dangerLevel=Math.min(5,(S.dangerLevel||1)+0.5);if(typeof updateDangerPips==='function')updateDangerPips();logMoveEvent([{type:'long_rest',restCount:S._longRestCount}]);saveState();if(typeof updateCampButtonHint==='function')updateCampButtonHint();const _hdNow=Math.max(0,maxHD-(S._hdUsed||0));let _lrText='🌙 <b>Descanso Longo</b><br><br>';_lrText+='❤️ HP totalmente recuperado<br>';_lrText+='✨ Condi\u00e7\u00f5es removidas<br>';if(prevExhaustion>0)_lrText+=`⚠️ Exaust\u00e3o: ${prevExhaustion} \u2192 ${S.exhaustion}<br>`;else _lrText+='✅ Sem exaust\u00e3o<br>';if(S.charData&&S.charData.mm>0)_lrText+='✨ MP totalmente recuperado<br>';_lrText+=`🎲 Dados de Vida: ${_hdNow}/${maxHD} (+${hdRecov} recuperados)<br>`;if(S.weather==='t')_lrText+='<br>⚡ <span style="color:#dca028">Tempestade: descanso dif\u00edcil, +1 exaust\u00e3o.</span>';else if(S.weather==='r')_lrText+='<br>🌧️ <span style="color:#8a7a68">Chuva: descanso desconfort\u00e1vel.</span>';if(S._longRestCount>1)_lrText+='<br>⚠️ <span style="color:#dca028">O perigo da regi\u00e3o aumentou.</span>';_lrText+='<br><i>Voc\u00ea se sente revigorado.</i>';_showLongRestDice(_lrText);}
function _checkLongRestAmbush(){const weatherBonus=S.weather==='t'?15:S.weather==='r'?5:0;const ambushChance=20+((S._longRestCount-1)*15)+weatherBonus;const roll=Math.floor(Math.random()*100)+1;if(roll<=ambushChance&&S.campAmbush&&!S._campAmbushUsed){if(S._guardSuccess){const avoidRoll=Math.floor(Math.random()*100)+1;if(avoidRoll<=50){S._longRestAmbushSafe=true;showTerrainToast('\ud83d\udee1\ufe0f Sua vig\u00edlia afastou uma amea\u00e7a!','ranger');return;}
showTerrainToast('\u26a0\ufe0f Voc\u00ea detectou a amea\u00e7a, prepare-se!','condition');}}else{S._longRestAmbushSafe=true;}}
var _lrDice=null;function _showLongRestDice(summaryHtml){const overlay=document.getElementById('camp-dice-overlay');const canvas=document.getElementById('camp-dice-canvas');const label=document.getElementById('camp-dice-label');if(!overlay||!canvas||typeof Dice3D==='undefined'){_showLongRestSummary(summaryHtml);return;}
const hdType=(S.charData&&S.charData.hdt)||'1d8';const dieShape=hdType.replace(/^\d+/,'');const sides=parseInt(dieShape.replace('d',''))||8;const dieResult=sides;label.textContent='';overlay.classList.add('active');try{if(_lrDice){_lrDice.dispose();_lrDice=null;}
_lrDice=new Dice3D(canvas,{size:140,dieType:dieShape,duration:1200});}catch(e){console.warn('[EXPLORE] Long Rest Dice3D init failed:',e);overlay.classList.remove('active');_showLongRestSummary(summaryHtml);return;}
_lrDice.roll(dieResult,function(){label.textContent=hdType+' = '+dieResult+' (Descanso Longo)';if(window.vHaptic)vHaptic.medium();var _lrDelay=typeof calcReadTime==='function'?calcReadTime('Descanso Longo resultado dado','result'):3000;setTimeout(function(){overlay.classList.remove('active');if(_lrDice){_lrDice.dispose();_lrDice=null;}
_showLongRestSummary(summaryHtml);},_lrDelay);});}
function _showLongRestSummary(summaryHtml){var overlay=document.getElementById('camp-result-overlay');var resultEl=document.getElementById('camp-result-text');if(overlay&&resultEl){resultEl.innerHTML=summaryHtml;overlay.classList.add('active');}else{showTerrainToast('Descanso Longo: HP recuperado','ranger');}
_checkLongRestAmbush();}
var _campDice=null;function _showCampDiceRoll(roll,conMod,bonus,total,foodName,hdType,mpRecovered){const overlay=document.getElementById('camp-dice-overlay');const canvas=document.getElementById('camp-dice-canvas');const label=document.getElementById('camp-dice-label');if(!overlay||!canvas){showCampResultOverlay(roll,conMod,bonus,total,foodName);return;}
label.textContent='';overlay.classList.add('active');try{if(_campDice){_campDice.dispose();_campDice=null;}
const dieShape=(hdType||'1d8').replace(/^\d+/,'');_campDice=new Dice3D(canvas,{size:140,dieType:dieShape,duration:1200});}catch(e){console.warn('[EXPLORE] Camp Dice3D init failed:',e);overlay.classList.remove('active');showCampResultOverlay(roll,conMod,bonus,total,foodName);return;}
_campDice.roll(roll,function(){const sign=conMod>=0?'+':'';label.textContent=`${hdType || '1d8'} = ${roll} ${sign}${conMod} (CON)`;if(window.vHaptic)vHaptic.medium();const _campResultText=`${hdType || '1d8'} = ${roll} ${sign}${conMod} (CON) = ${roll + conMod}`;const _campDelay=typeof calcReadTime==='function'?calcReadTime(_campResultText,'result'):3000;setTimeout(function(){overlay.classList.remove('active');if(_campDice){_campDice.dispose();_campDice=null;}
showCampResultOverlay(roll,conMod,bonus,total,foodName,hdType,mpRecovered);},_campDelay);});}
function showCampResultOverlay(roll,conMod,bonus,total,foodName,hdType,mpRecovered){var overlay=document.getElementById('camp-result-overlay');var resultText=document.getElementById('camp-result-text');var detailEl=document.getElementById('camp-result-detail');resultText.textContent='+'+total+' HP Restaurados';resultText.style.animation='none';resultText.offsetHeight;resultText.style.animation='resultReveal 0.5s var(--v-ease-spring, cubic-bezier(0.34, 1.56, 0.64, 1))';var sign=conMod>=0?'+':'';var detail=(hdType||'1d8')+' = '+roll+' '+sign+' '+conMod+' (CON) = '+(roll+conMod);if(bonus>0)detail+='\n'+foodName+': +'+bonus+' HP';if(mpRecovered>0)detail+='\n\u2728 +'+mpRecovered+' MP recuperado';var maxHD=(S.charData&&S.charData.mhd)||1;var hdRemaining=Math.max(0,maxHD-(S._hdUsed||0));var currentHP=getCurrentHP();var maxHP=getMaxHP();var hpPct=Math.max(2,Math.round((currentHP/maxHP)*100));var hpColor=hpPct>60?'#4caf50':hpPct>25?'#f97316':'#ef4444';detail+='\n';detailEl.textContent=detail;var barContainer=document.createElement('div');barContainer.className='camp-hp-bar-container';barContainer.style.cssText='margin-top:8px;padding:0 12px';barContainer.innerHTML='<div style="display:flex;align-items:center;gap:8px;font-size:12px;color:#8a7a68">'+'<span>HP</span>'+'<div style="flex:1;height:8px;background:rgba(0,0,0,0.3);border-radius:4px;overflow:hidden;border:1px solid rgba(255,255,255,0.08)">'+'<div id="camp-hp-fill" style="height:100%;background:'+hpColor+';border-radius:3px;transition:width 0.8s ease;width:0%"></div>'+'</div>'+'<span style="color:'+hpColor+'">'+currentHP+'/'+maxHP+'</span>'+'</div>'+'<div style="text-align:center;font-size:11px;color:#8a7a68;margin-top:4px">Dados de Vida: '+hdRemaining+'/'+maxHD+'</div>';detailEl.parentElement.appendChild(barContainer);overlay.classList.add('active');if(window.vHaptic)vHaptic.success();if(typeof flashScreen==='function')flashScreen('rgba(68,170,136,0.15)');setTimeout(function(){var fill=document.getElementById('camp-hp-fill');if(fill)fill.style.width=hpPct+'%';},200);}
function closeCampResult(){var campResultOverlay=document.getElementById('camp-result-overlay');var bars=campResultOverlay.querySelectorAll('.camp-hp-bar-container');bars.forEach(function(b){b.remove();});campResultOverlay.classList.remove('active');if(typeof setCampfireActive==='function')setCampfireActive(false);S._lowHPAlertShown=false;if(S.campAmbush&&!S._campAmbushUsed&&!S._longRestAmbushSafe){S._campAmbushUsed=true;saveState();showTerrainToast('Algo ataca durante seu descanso!','danger');setTimeout(()=>{triggerCombat({combat:S.campAmbush});},1500);return;}
S._longRestAmbushSafe=false;if(_returningToCity&&_returnJourney){setTimeout(()=>{document.getElementById('return-journey-overlay').classList.add('active');_renderReturnHP(document.getElementById('return-journey-hp'));const remaining=_returnJourney.totalSteps-_returnJourney.currentStep;const actionsEl=document.getElementById('return-journey-actions');const overlay=document.getElementById('return-journey-overlay');_addReturnActions(actionsEl,overlay,remaining);},400);}}
function checkLowHP(){const pct=getHPPercent();if(pct>25||pct<=0)return false;if(S._lowHPAlertShown)return false;S._lowHPAlertShown=true;showLowHPOverlay();return true;}
function showLowHPOverlay(){const overlay=document.getElementById('lowhp-overlay');const hpRow=document.getElementById('lowhp-hp-row');const optionsEl=document.getElementById('lowhp-options');const currentHP=getCurrentHP();const maxHP=getMaxHP();const hpPct=getHPPercent();const distance=bfsDistanceToExit(S.playerCol,S.playerRow);const risk=calculateExitRisk(distance);hpRow.innerHTML=`<span>HP</span>`+`<div class="exit-hp-bar"><div class="exit-hp-fill" style="transform:scaleX(${Math.max(0.02, hpPct/100)});background:#c44"></div></div>`+`<span style="color:#c44">${currentHP}/${maxHP}</span>`;optionsEl.innerHTML='';const healItems=getHealingItems();for(const item of healItems.slice(0,2)){addExitOption(optionsEl,item.e||'',`Usar ${item.n} (${item.q}x)`,`Restaura ${item.h} HP`,'#4a8',()=>{overlay.classList.remove('active');useInventoryItemAnimated(item,(heal)=>{showTerrainToast(`${item.e || ''} +${heal} HP`,'ranger');S._lowHPAlertShown=false;});});}
const distText=distance>=0?`${distance} turnos`:'???';addExitOption(optionsEl,'',`Retornar (${distText})`,`Risco: ${risk.label} (${risk.chance}%)`,risk.color,()=>{overlay.classList.remove('active');attemptReturnToCity(risk.chance);});addExitOption(optionsEl,'','Continuar Explorando','Arriscar seguir adiante','#8a7a68',()=>{overlay.classList.remove('active');});overlay.classList.add('active');if(window.vHaptic)vHaptic.warning();}
function _checkHealingSpring(){if(!S.charData)return false;if(S._healingSpringUsed)return false;var currentHP=S.charData.hp+(S.hpChange||0);var maxHP=S.charData.mh||10;var hpPct=currentHP/maxHP;var chance=0;if(hpPct<0.25)chance=30;else if(hpPct<0.50)chance=15;else return false;var roll=Math.floor(Math.random()*100)+1;if(roll>chance)return false;S._healingSpringUsed=true;_showHealingSpring();return true;}
function _showHealingSpring(){activateOverlay('dm-overlay');var overlay=document.getElementById('dm-overlay');var textEl=document.getElementById('dm-narration');var choicesEl=document.getElementById('dm-choices');if(!overlay||!textEl)return;var biome=S.currentBiome||'forest';var springs={forest:{name:'Fonte Silvestre',desc:'Uma nascente cristalina brota entre as ra\u00edzes de um carvalho ancestral. A \u00e1gua brilha com um toque de magia.'},plains:{name:'Po\u00e7o do Peregrino',desc:'Um po\u00e7o de pedra desgastado pelo tempo. A \u00e1gua fresca parece curar mais do que a sede.'},desert:{name:'O\u00e1sis Oculto',desc:'Entre as dunas, uma po\u00e7a de \u00e1gua l\u00edmpida cercada por tamareiras. Uma miragem... que \u00e9 real.'},snow:{name:'Fonte Termal',desc:'Vapor sobe de uma po\u00e7a quente na neve. A \u00e1gua mineral aquece e revigora.'},swamp:{name:'Claro do P\u00e2ntano',desc:'Um c\u00edrculo de \u00e1gua estranhamente pura no meio do p\u00e2ntano. Flores azuis flutuam na superf\u00edcie.'},mountain:{name:'Cascata da Montanha',desc:'Uma pequena cascata desce entre as rochas. A \u00e1gua gelada \u00e9 revigorante.'},cave:{name:'Lago Subterr\u00e2neo',desc:'Um lago de \u00e1gua parada que brilha com luz pr\u00f3pria. Cogumelos luminescentes cercam suas margens.'},volcanic:{name:'Fonte Mineral',desc:'A \u00e1gua borbulha quente da terra vulc\u00e2nica. Minerais dissolvidos d\u00e3o-lhe propriedades curativas.'},graveyard:{name:'Santu\u00e1rio Esquecido',desc:'Uma est\u00e1tua coberta de musgo abriga uma fonte de \u00e1gua benta. A paz emana deste lugar.'},};var spring=springs[biome]||springs.forest;var wisMod=typeof getAbilityMod==='function'?getAbilityMod('ws'):0;var healRoll=Math.floor(Math.random()*8)+1;var totalHeal=Math.max(1,healRoll+wisMod);textEl.innerHTML='<div style="text-align:center">'+'<div style="font-size:14px;color:#4a8;font-weight:700;margin-bottom:8px">\u26f2 '+spring.name+'</div>'+'<div style="font-size:13px;color:#d4c8b0;line-height:1.6;margin-bottom:10px">'+spring.desc+'</div>'+'<div style="font-size:12px;color:#4a8;background:rgba(68,170,136,0.1);padding:6px 10px;border-radius:8px;border:1px solid rgba(68,170,136,0.2)">'+'\ud83c\udfb2 1d8+'+wisMod+' = <b>+'+totalHeal+' HP</b> recuperados</div></div>';S.hpChange=(S.hpChange||0)+totalHeal;var newHP=Math.min(S.charData.mh,S.charData.hp+S.hpChange);updateHP(newHP,S.charData.mh);if(typeof spawnFloatingText==='function')spawnFloatingText(S.col,S.row,'+'+totalHeal+' HP','#4a8','damage');choicesEl.innerHTML='';var readDelay=typeof calcReadTime==='function'?calcReadTime(spring.desc,'dm'):3500;setTimeout(function(){overlay.classList.remove('active');if(typeof setEventActive==='function')setEventActive(false);saveState();},readDelay);}
function checkDeath(){if(!S.charData)return false;const currentHP=S.charData.hp+S.hpChange;if(currentHP<=0){if(!S._secondWindUsed){S._secondWindUsed=true;_showSecondWind();return true;}
showDeathSaves();return true;}
return false;}
function _showSecondWind(){var overlay=document.getElementById('check-overlay');var formulaEl=document.getElementById('check-formula');var resultEl=document.getElementById('check-result');if(!overlay){showDeathSaves();return;}
formulaEl.innerHTML='<div style="font-size:14px;color:#c44;margin-bottom:6px">\u2620\ufe0f Voc\u00ea cai...</div>'+'<div style="font-size:12px;color:#a09484;line-height:1.5">Mas algo dentro de voc\u00ea se recusa a ceder.<br>'+'<span style="color:#c4953a">F\u00f4lego (1x por explora\u00e7\u00e3o)</span></div>'+'<div style="font-size:11px;color:#8a7a68;margin-top:6px">d20 \u2265 10 para sobreviver</div>';resultEl.textContent='';resultEl.className='check-result';overlay.classList.add('active');var readDelay=typeof calcReadTime==='function'?calcReadTime('Voce cai mas algo dentro de voce se recusa a ceder','overlay'):2500;setTimeout(function(){var result=rollD20('normal');var roll=result.roll;var success=roll>=10;var dice=getDice3D();if(dice){dice.roll(roll,function(){_resolveSecondWind(overlay,formulaEl,resultEl,roll,success);});}else{_resolveSecondWind(overlay,formulaEl,resultEl,roll,success);}},readDelay);}
function _resolveSecondWind(overlay,formulaEl,resultEl,roll,success){if(success){S.hpChange=-(S.charData.hp-1);updateHP(1,S.charData.mh);addExhaustion(2,'F\u00f4lego');resultEl.innerHTML='<div style="color:#4a8;font-size:16px;font-weight:700">\u2705 F\u00f4lego!</div>'+'<div style="font-size:12px;color:#a09484;margin-top:4px">\ud83c\udfb2 '+roll+' \u2265 10</div>'+'<div style="font-size:11px;color:#c4953a;margin-top:6px">Voc\u00ea sobrevive com 1 HP + 2 n\u00edveis de exaust\u00e3o.</div>';if(window.vHaptic)vHaptic.notify('success');}else{resultEl.innerHTML='<div style="color:#c44;font-size:16px;font-weight:700">\u274c Escurid\u00e3o...</div>'+'<div style="font-size:12px;color:#a09484;margin-top:4px">\ud83c\udfb2 '+roll+' < 10</div>'+'<div style="font-size:11px;color:#c44;margin-top:6px">O f\u00f4lego n\u00e3o foi suficiente.</div>';if(window.vHaptic)vHaptic.notify('error');}
var readDelay=typeof calcReadTime==='function'?calcReadTime(success?'Folego sobrevive com 1 HP':'Escuridao o folego nao foi suficiente','result'):4000;setTimeout(function(){overlay.classList.remove('active');if(typeof disposeDice3D==='function')disposeDice3D();if(!success){showDeathSaves();}else{saveState();}},readDelay);}
var DEATH_SAVE_NARRATIONS=['O mundo escurece nas bordas. Cada batida do coração parece mais fraca que a anterior...','Vozes sussurram ao longe. Serão os deuses decidindo seu destino?','Uma luz fraca brilha além da escuridão. Ainda não é hora de segui-la.','Memórias passam como sombras. Você se agarra ao fio de vida que resta.','O frio se instala. Seus dedos formigam. A luta entre vida e morte continua.',];function showDeathSaves(){var overlay=document.getElementById('death-overlay');var summary=document.getElementById('death-summary');overlay.classList.add('active');if(window.vHaptic)vHaptic.error();var successes=0,failures=0,rollNum=0;var _done=false;function renderState(roll,isResult,narrText){var sMarks='●'.repeat(successes)+'○'.repeat(3-successes);var fMarks='●'.repeat(failures)+'○'.repeat(3-failures);var html='<div style="text-align:center;margin-bottom:12px">'+'<div style="font-size:18px;margin-bottom:8px">Salvaguardas contra Morte</div>'+'<div style="font-size:14px;color:#6a8">✓ '+sMarks+'</div>'+'<div style="font-size:14px;color:#a66">✗ '+fMarks+'</div>'+'</div>';if(narrText){html+='<div style="text-align:center;font-size:12px;color:#a09484;line-height:1.5;margin:8px 12px;font-style:italic">'+narrText+'</div>';}
if(roll!==null){var color=roll===20?'#ffd700':roll===1?'#ff3333':roll>=10?'#6a8':'#a66';html+='<div style="text-align:center;margin:12px 0">'+'<div class="dice-result" style="font-size:clamp(22px,6vw,28px);color:'+color+'">'+roll+'</div>'+'<div style="font-size:12px;color:#8a7a68;margin-top:4px">Rolagem '+rollNum+'</div>'+'</div>';}
if(isResult){if(successes>=3){html+='<div style="text-align:center;color:#6a8;font-size:16px;margin-top:12px">Estabilizado! Você acorda com 1 HP.</div>';}else if(failures>=3){html+='<div style="text-align:center;color:#a66;font-size:16px;margin-top:12px">Você sucumbe aos ferimentos...</div>';}else if(roll===20){html+='<div style="text-align:center;color:#ffd700;font-size:16px;margin-top:12px">Crítico Natural! Você se levanta com 1 HP!</div>';}}
summary.innerHTML=html;}
function rollDeathSave(){if(_done)return;rollNum++;var narrIdx=(rollNum-1)%DEATH_SAVE_NARRATIONS.length;var narrText=DEATH_SAVE_NARRATIONS[narrIdx];renderState(null,false,narrText);var result=typeof rollD20==='function'?rollD20('normal'):{roll:Math.floor(Math.random()*20)+1};var roll=result.roll;var narrDelay=typeof calcReadTime==='function'?calcReadTime(narrText,'combat'):1500;setTimeout(function(){if(_done)return;var dice=typeof getDice3D==='function'?getDice3D():null;var afterDice=function(){if(roll===20){successes=3;renderState(roll,true,null);if(window.vHaptic)vHaptic.success();flashScreen('rgba(255,215,0,0.3)');setTimeout(function(){if(_done)return;_done=true;if(typeof disposeDice3D==='function')disposeDice3D();overlay.classList.remove('active');S.hpChange=-(S.charData.hp-1);updateHP(1);saveState();},2500);return;}
if(roll===1){failures+=2;}
else if(roll>=10){successes++;}
else{failures++;}
var isFinal=successes>=3||failures>=3;renderState(roll,isFinal,null);if(roll>=10&&roll!==20){if(window.vHaptic)vHaptic.notify('success');}else{if(window.vHaptic)vHaptic.notify('error');}
if(roll===1){flashScreen('rgba(200,0,0,0.4)');if(typeof document.body.animate==='function'){document.body.animate([{transform:'translateX(-3px)'},{transform:'translateX(3px)'},{transform:'translateX(-2px)'},{transform:'translateX(2px)'},{transform:'translateX(0)'},],{duration:300,easing:'ease-out'});}}
if(typeof disposeDice3D==='function')disposeDice3D();if(successes>=3){if(typeof flashScreen==='function')flashScreen('rgba(68,170,136,0.2)');setTimeout(function(){if(_done)return;_done=true;overlay.classList.remove('active');S.hpChange=-(S.charData.hp-1);updateHP(1);saveState();showTerrainToast('Voce se estabiliza. A escuridao recua.','ranger');},2500);}else if(failures>=3){if(typeof flashScreen==='function')flashScreen('rgba(100,0,0,0.4)');setTimeout(function(){if(_done)return;_done=true;finishExploration('death');},3000);}else{setTimeout(rollDeathSave,1200);}};if(dice){dice.roll(roll,afterDice);}else{if(typeof _emojiFallbackDie==='function'){var dsOverlay=document.getElementById('check-overlay')||document.getElementById('death-save-overlay');_emojiFallbackDie(dsOverlay,roll,afterDice);}else{var fb=document.createElement('div');fb.style.cssText='font-size:32px;text-align:center';var fNums=['\u2680','\u2681','\u2682','\u2683','\u2684','\u2685'];var fIdx=0;var fIv=setInterval(function(){fb.textContent=fNums[fIdx++%6];},80);var dsTarget=document.getElementById('check-overlay')||document.getElementById('death-save-overlay');if(dsTarget)dsTarget.appendChild(fb);setTimeout(function(){clearInterval(fIv);fb.textContent=roll;setTimeout(afterDice,400);},700);}}},narrDelay);}
renderState(null,false,null);setTimeout(rollDeathSave,1000);}
function showDeathOverlay(){const overlay=document.getElementById('death-overlay');const summary=document.getElementById('death-summary');let html='';if(S.xpEarned>0)html+=`<div class="reward-line">+${S.xpEarned} XP</div>`;if(S.goldEarned>0)html+=`<div class="reward-line">+${S.goldEarned} Ouro</div>`;html+=`<div class="reward-line">HP reduzido a 0</div>`;summary.innerHTML=html;overlay.classList.add('active');let _deathDone=false;const skipBtn=document.getElementById('death-skip-btn');const finishDeath=()=>{if(_deathDone)return;_deathDone=true;if(skipBtn){skipBtn.classList.remove('visible');skipBtn.onclick=null;}
finishExploration('death');};setTimeout(()=>{if(!_deathDone&&skipBtn){skipBtn.classList.add('visible');skipBtn.onclick=finishDeath;}},500);const deathText=summary.textContent||'';const deathDelay=typeof calcReadTime==='function'?calcReadTime(deathText,'summary'):2500;setTimeout(finishDeath,deathDelay);}
var _returningToCity=false;var _returnJourney=null;var _returnDice=null;var RETURN_NARRATIONS={forest:['As copas das árvores se fecham sobre a trilha, criando um túnel verde onde a luz do sol mal penetra. Galhos estalam sob seus pés enquanto pássaros silenciam à sua passagem — a floresta observa quem ousa cruzá-la.','Um riacho serpenteia ao lado do caminho, seu murmúrio constante acalma seus nervos. Marcas de garras em uma árvore próxima lembram que você não está sozinho nesta floresta, mas por ora o caminho está livre.','Raízes retorcidas tornam cada passo uma negociação. A trilha foi feita por animais, não por homens — mas é o caminho mais curto de volta. Você se agacha sob um tronco caído e continua.','A luz dourada do entardecer penetra entre os galhos, pintando o chão da floresta com sombras alongadas. O aroma de musgo e terra úmida enche seus pulmões. Por um momento, a jornada quase parece pacífica.','Pegadas de cervos cruzam a trilha em várias direções. A floresta tem seus próprios caminhos e seus próprios viajantes. Ao longe, o canto de um pássaro desconhecido ecoa como um aviso — ou talvez uma despedida.',],plains:['O vento varre os campos abertos, dobrando a grama alta em ondas douradas que se estendem até o horizonte. Você caminha pela estrada de terra, sentindo o sol aquecer suas costas. A cidade é apenas um ponto distante, mas cresce a cada passo.','Rebanhos selvagens pastam ao longe, indiferentes à sua passagem. A planície parece infinita sob o céu vasto, e o silêncio só é quebrado pelo farfalhar da grama. Seus pés encontram ritmo na estrada batida por mil viajantes antes de você.','Flores silvestres pontilham os campos, pintando o verde com toques de roxo e amarelo. O aroma doce mistura-se com o cheiro de terra seca. Uma brisa gentil empurra você na direção certa — como se a própria planície quisesse levá-lo de volta.','Uma colina suave revela a vastidão da estrada à frente. Ao longe, fumaça de chaminés sobe preguiçosamente — sinal de civilização. O cansaço da jornada é real, mas seus pés encontram novo vigor com a promessa de um teto seguro.','Nuvens se acumulam no horizonte, projetando sombras enormes sobre os campos. O vento muda de direção, trazendo consigo o cheiro de chuva. Você aperta o passo — melhor chegar antes que a tempestade alcance a estrada.',],cave:['O eco de seus passos é o único som nos túneis frios. Gotas de água caem do teto em intervalos regulares, como um relógio subterrâneo contando os minutos até a superfície. Suas mãos deslizam pela parede úmida, seguindo as marcações de giz.','Estalactites gotejam lentamente, criando poças cristalinas que refletem a luz bruxuleante da sua tocha. A passagem se estreita e depois se abre em uma câmara onde o ar é surpreendentemente fresco — um bom sinal de que a saída está próxima.','Cristais incrustados na rocha capturam a luz e a devolvem em faíscas multicoloridas. Por um instante, você para para apreciar a beleza oculta destas profundezas. Mas o caminho chama — e ficar parado demais nestas cavernas nunca é sábio.','Uma corrente de ar gelado atinge seu rosto, trazendo o cheiro inconfundível de vegetação. A superfície está perto. Você acelera o passo, ansioso para trocar a escuridão opressiva pela luz do dia e o ar livre.','Cogumelos luminescentes bordejam o caminho como lanternas fantasmagóricas. Seus tons azulados iluminam formações rochosas que parecem esculturas de algum artista subterrâneo. A natureza cria suas próprias maravilhas, mesmo nas profundezas.',],swamp:['A lama suga seus pés a cada passo, relutante em liberá-lo. O ar pesado e úmido enche seus pulmões como um cobertor molhado. Insetos zumbem ao redor, mas você mantém o foco na trilha elevada — o único caminho seguro neste pântano traiçoeiro.','Brumas espessas cobrem a superfície da água estagnada. Você segue as estacas de marcação fincadas por viajantes anteriores, cada uma um testemunho de que outros cruzaram este pântano e sobreviveram. O silêncio é quebrado apenas pelo coaxar distante de sapos.','Raízes de manguezais formam pontes naturais sobre a água escura, seus galhos retorcidos como dedos de uma criatura adormecida. Você equilibra-se sobre elas com cuidado, observando bolhas subindo na lama abaixo — algo se move nas profundezas.','O pântano exala seus gases pútridos enquanto o sol se esforça para penetrar a névoa persistente. Tábuas de madeira apodrecida marcam uma passadeira improvisada. Cada passo é uma aposta, mas você conhece os sinais de madeira podre e avança com cautela.','Luzes fantasmagóricas dançam sobre a superfície da água — fogo-fátuo, dizem os viajantes. Belas, mas traiçoeiras. Você desvia o olhar e mantém os pés firmes na trilha. O pântano já engoliu muitos que se deixaram seduzir por suas luzes.',],mountain:['O vento frio corta como lâmina nas passagens altas da montanha. Cada respiração é uma conquista nesta altitude, e seus músculos protestam na subida. Mas a vista panorâmica revela o vale distante onde Eldoria repousa — motivação suficiente para continuar.','Pedras soltas rolam sob seus pés, ecoando pelo desfiladeiro como tambores de guerra. A trilha serpenteia entre paredões de rocha escura, e você se mantém próximo à parede interna. Um olhar para o precipício confirma: não há margem para erro.','Cabras montesas observam sua passagem de uma saliência acima, suas silhuetas recortadas contra o céu cinzento. Elas conhecem estas montanhas melhor que qualquer mapa. Você segue o mesmo caminho que elas trilharam por gerações — o mais seguro.','Uma nascente brota da rocha, sua água gelada e cristalina. Você bebe e enche seu cantil, agradecendo por este pequeno presente da montanha. O frio nas mãos é um preço barato pelo revigor que a água traz aos seus membros cansados.','O caminho desce agora, e cada passo é um alívio depois da longa escalada. As árvores começam a reaparecer, primeiro arbustos raquíticos, depois pinheiros firmes. A montanha está ficando para trás, e com ela, os piores perigos da jornada.',],desert:['O sol escaldante castiga a areia interminável. Miragens dançam no horizonte, prometendo oásis que não existem. Você puxa o capuz sobre os olhos e segue as marcações de pedra empilhada — a única prova de que outros já cruzaram esta desolação antes.','Dunas imensas mudam lentamente sob o vento, redesenhando o deserto a cada hora. A areia fina se infiltra em cada fresta da armadura, irritando a pele. Você usa as estrelas e o sol como bússola, mantendo o rumo mesmo quando a trilha desaparece.','Um oásis seco é tudo que resta de uma antiga fonte — ossos brancos de animais ao redor contam a história. Mas adiante, rochas projetam uma sombra abençoada. Você descansa brevemente, recuperando forças antes de enfrentar o próximo trecho exposto.','Lagartos escalam as rochas aquecidas pelo sol, os únicos seres vivos visíveis nesta vastidão. O silêncio é ensurdecedor, quebrado apenas pelo sussurro da areia no vento. Seus passos deixam pegadas que serão apagadas em minutos — o deserto não guarda memórias.','O horizonte finalmente muda. Onde antes havia apenas areia, agora surgem os primeiros arbustos resistentes e, além deles, uma linha verde promissora. O deserto está cedendo terreno. Você sente a umidade no ar aumentar e respira fundo — o pior ficou para trás.',],snow:['A neve range sob seus pés com cada passo, um som ritmado que se tornou companhia constante. O frio morde cada pedaço de pele exposta, e sua respiração forma nuvens densas no ar gelado. Mas o caminho está firme — neve compactada por muitas passagens.','Uma trilha de pegadas antigas guia seu caminho entre os montes de neve. Alguém — ou algo — passou por aqui recentemente. Você segue os rastros com cautela, atento a qualquer sinal de perigo, mas agradecido por não ter que abrir caminho na neve virgem.','Pinheiros cobertos de gelo formam uma catedral branca ao redor da trilha. Flocos de neve caem suavemente, cobrindo a paisagem em um silêncio reverente. A beleza é hipnotizante, mas o frio é real — você mantém as mãos em movimento dentro das luvas.','O vento uiva entre os pinheiros, levantando redemoinhos de neve que reduzem a visibilidade. Você se abaixa e avança, usando as árvores como abrigo. Entre as rajadas, consegue vislumbrar a trilha descendo — sinal de que está deixando as alturas nevadas.','Cristais de gelo brilham como diamantes sob a fraca luz do sol que rompe as nuvens. A paisagem é de uma beleza cruel — esplêndida aos olhos, mortal para quem se perde. Você confere suas marcações e segue em frente, os olhos fixos no caminho.',],volcanic:['O chão estremece sob seus pés enquanto geysers de vapor irrompem das fendas. O ar é denso, carregado de enxofre e cinzas que irritam os olhos. Cada passo é uma negociação com a terra instável — mas a trilha de obsidiana oferece passagem segura.','Rios de lava serpenteiam ao longe, pintando o horizonte de laranja e vermelho. O calor é opressivo mesmo a esta distância. Você segue as pedras marcadas com runas de proteção, deixadas por desbravadores que mapearam esta rota vulcânica.','Cristais de enxofre brilham como joias tóxicas entre as rochas negras. A beleza mortal do vulcão é hipnotizante, mas o tremor constante sob seus pés é um lembrete implacável: esta terra está viva e não tolera intrusos demorados.','Cinzas vulcânicas cobrem o caminho como neve negra, abafando seus passos. No horizonte, a silhueta escura do vulcão se recorta contra um céu avermelhado. A cada metro que se afasta, o ar fica mais respirável e a temperatura cede.','Uma ponte natural de basalto cruza uma fissura fumegante. O calor que sobe queima o rosto, mas a rocha é sólida. Do outro lado, a vegetação começa a reaparecer — sinal de que está deixando o domínio do vulcão para trás.',],graveyard:['Lápides tortas e cruzes apodrecidas pontilham o caminho como sentinelas silenciosas. A névoa se agarra ao chão, ocultando raízes e pedras soltas. Você caminha entre os mortos com respeito cauteloso — neste lugar, respeito pode salvar vidas.','Corvos observam sua passagem dos galhos secos de árvores mortas. Seus olhos negros e brilhantes seguem cada movimento. O silêncio é antinatural — nem insetos ousam cantar neste solo amaldiçoado. Apenas seus passos quebram a quietude.','A terra aqui tem uma qualidade estranha — macia demais, como se recusasse ser pisada. Mausoléus de pedra erguem-se entre a névoa, seus portões de ferro enferrujados rangendo com o vento. Algo sussurra, mas são apenas folhas secas. Provavelmente.','Uma trilha de pedras brancas — ossos, percebe com um calafrio — guia seu caminho entre túmulos antigos. As inscrições são ilegíveis, gastas pelo tempo. Mas as flores murchas recentes indicam que alguém ainda visita os mortos. Ou algo.','A névoa se abre por um instante, revelando os muros distantes de Eldoria além do cemitério. A promessa de civilização acelera seus passos. Atrás de você, jura ouvir um suspiro — mas quando olha, há apenas pedras e silêncio.',],_default:['A estrada se estende à sua frente, seus paralelepípedos gastos por mil viajantes. Cada passo aproxima você da segurança dos muros de Eldoria. O peso da exploração se faz sentir nos ombros, mas a determinação mantém seus pés firmes na trilha.','O terreno familiar traz um certo alívio — você reconhece uma árvore marcada, uma curva na estrada. Estas terras já não são desconhecidas. Sons de civilização começam a se misturar com os sons da natureza: um carro distante, vozes abafadas.','Sons distantes ecoam pela trilha. Viajantes ou perigo? Impossível dizer a esta distância. Você mantém a mão próxima à arma e os olhos atentos, mas não desacelera. Cada momento parado é um momento a mais em território hostil.','Um marco de pedra surge ao lado do caminho, gravado com a runa de Eldoria. A cidade não está longe — estas marcações são colocadas a cada meia légua dos portões. O alívio começa a se instalar, mas você sabe que os últimos passos são os mais traiçoeiros.','O cansaço pesa como chumbo em seus membros, mas no horizonte, as torres de vigia de Eldoria começam a se erguer contra o céu. A promessa de uma cama quente, comida e segurança motiva seus passos. Só mais um pouco — só mais um pouco.',],};var RETURN_HAZARDS={forest:[{icon:'',title:'Teias Gigantes',narr:'Teias enormes bloqueiam a trilha entre os troncos, grossas como cordas e pegajosas ao toque. Casulos pendem dos galhos — o que as teceu é grande e ainda está por perto.',choices:[{i:'',t:'Queimar as teias',k:{s:'int',dc:10},sNarr:'Você improvisa uma tocha com galhos secos e queima as teias com precisão. As chamas consomem os fios sem se espalhar.',fNarr:'O fogo se espalha descontrolado! Você recua, mas as chamas alcançam seu braço antes que consiga apagá-las.',fDmg:3},{i:'',t:'Desviar por baixo',k:{s:'dex',dc:12},sNarr:'Com movimentos calculados, você desliza sob as teias sem tocar em um único fio. Limpo e silencioso.',fNarr:'As teias são mais baixas do que pareciam. Fios grudam em suas costas e puxam — quanto mais se debate, mais se enrosca.',fDmg:4},{i:'',t:'Forçar passagem',k:{s:'str',dc:13},sNarr:'Com um grito de esforço, você rasga as teias como cortinas e abre caminho à força bruta.',fNarr:'As teias são resistentes como aço! Seu braço fica preso e a vibração certamente alertou o que vive aqui.',fDmg:3},]},{icon:'',title:'Território de Urso',narr:'Marcas de garras profundas nos troncos, casca arrancada, chão revolto. O ar carrega o cheiro forte e almiscarado do animal — ele esteve aqui há pouco tempo.',choices:[{i:'',t:'Contornar em silêncio',k:{s:'dex',dc:12},sNarr:'Controlando até a respiração, você traça uma rota alternativa. O urso nem percebe sua passagem.',fNarr:'Um galho estala sob seu pé como um trovão no silêncio! O urso ergue a cabeça e avança com um urro.',fDmg:5},{i:'',t:'Ler os sinais da natureza',k:{s:'wis',dc:11},sNarr:'Rastros frescos apontam para o norte — o urso se afastou. Você cruza o território pela rota oposta.',fNarr:'Você interpreta os sinais ao contrário. O caminho que parecia seguro leva direto à toca.',fDmg:5},{i:'',t:'Fazer barulho para afastar',k:{s:'cha',dc:13},sNarr:'Batendo as mãos e gritando, você se faz parecer maior. O urso bufa e se retira pesadamente.',fNarr:'O urso interpreta seus gritos como desafio! Ele avança e você foge com arranhões profundos.',fDmg:6},]},{icon:'',title:'Raízes Traiçoeiras',narr:'O chão da floresta se transformou em um labirinto de raízes expostas, retorcidas e entrelaçadas como serpentes petrificadas. A trilha desapareceu sob esta teia vegetal.',choices:[{i:'',t:'Caminhar com cautela',k:{s:'wis',dc:10},sNarr:'Olhos atentos mapeiam cada passo. Você navega o trecho como quem lê um mapa no chão.',fNarr:'Uma raiz que parecia firme cede! Você tropeça e cai pesadamente, batendo o joelho em uma rocha.',fDmg:2},{i:'',t:'Correr e saltar',k:{s:'dex',dc:12},sNarr:'Com saltos ágeis de raiz em raiz, você atravessa o trecho como um acrobata.',fNarr:'Seu pé engancha em uma raiz oculta no meio do salto! A queda é dolorosa e seu tornozelo protesta.',fDmg:3},]},],plains:[{icon:'',title:'Ventania Repentina',narr:'Nuvens negras surgem do nada sobre a planície. O vento se intensifica em segundos, arrancando grama e levantando poeira. Sem abrigo natural à vista, você precisa decidir rápido.',choices:[{i:'',t:'Resistir de pé',k:{s:'str',dc:11},sNarr:'Fincando os pés no chão e curvando-se contra o vento, você resiste com determinação. Quando passa, ainda está de pé.',fNarr:'Uma rajada mais forte derruba você de costas! Detritos arrastados pelo vento cortam sua pele exposta.',fDmg:3},{i:'',t:'Buscar abrigo',k:{s:'wis',dc:10},sNarr:'Olhos treinados identificam uma depressão no terreno. Você se abriga ali até a tempestade passar.',fNarr:'Não há abrigo nesta planície maldita. A ventania castiga sem piedade enquanto busca em vão por cobertura.',fDmg:4},]},{icon:'',title:'Buraco Oculto',narr:'A grama alta e densa esconde o terreno real. Tocas de animais e erosão criaram um campo minado de buracos invisíveis. Um passo errado pode custar um tornozelo.',choices:[{i:'',t:'Observar o terreno',k:{s:'wis',dc:11},sNarr:'Você nota as diferenças na grama que denunciam os buracos. Com passos cuidadosos, desvia de todos.',fNarr:'Seu pé afunda até o joelho em um buraco invisível! Seu tornozelo gira com um estalo doloroso.',fDmg:4},{i:'',t:'Correr pelo campo',k:{s:'dex',dc:12},sNarr:'Reflexos afiados e passos leves levam você pelo campo. Quando um buraco aparece, seus pés já acharam outro apoio.',fNarr:'Na velocidade, impossível ver os buracos. Um deles engole seu pé e o impulso faz o resto — queda brusca.',fDmg:3},]},],cave:[{icon:'',title:'Desmoronamento',narr:'Um estrondo ecoa pelo túnel! Pedras se soltam do teto em cascata, rachaduras se espalham pelas paredes. Poeira enche o ar e a passagem começa a ceder.',choices:[{i:'',t:'Correr para o outro lado',k:{s:'dex',dc:13},sNarr:'Você dispara pela passagem em colapso! Pedras caem ao redor, mas seus pés são mais rápidos. Escapa por um fio.',fNarr:'Pedras enormes caem sobre você antes que alcance o outro lado! Dor aguda percorre seu corpo sob os escombros.',fDmg:6},{i:'',t:'Proteger-se e esperar',k:{s:'cn',dc:11},sNarr:'Você se encolhe sob uma saliência de rocha sólida. O desmoronamento passa e você emerge coberto de poeira mas intacto.',fNarr:'A saliência não era tão sólida. Uma pedra acerta seu ombro com força apesar da proteção improvisada.',fDmg:4},{i:'',t:'Analisar a estrutura',k:{s:'int',dc:12},sNarr:'Em um relance, você identifica os pilares naturais e traça uma rota entre os pontos de sustentação. Sem um arranhão.',fNarr:'Sua análise parecia correta, mas a rocha neste ponto era friável. O caminho que escolheu desaba sob seus pés.',fDmg:5},]},{icon:'',title:'Gás Venenoso',narr:'Um cheiro pungente e sulfuroso emana de uma fissura na rocha. O ar ganha uma tonalidade esverdeada e seus olhos ardem. Gás tóxico, espalhando-se pelo túnel.',choices:[{i:'',t:'Prender a respiração',k:{s:'cn',dc:12},sNarr:'Você inspira fundo o último ar limpo e atravessa a zona contaminada em apneia. Seus pulmões ardem, mas resiste.',fNarr:'O trecho é mais longo do que calculou! O gás irrita seus pulmões. Tosse violenta e náusea se seguem.',fDmg:4},{i:'',t:'Buscar corrente de ar',k:{s:'int',dc:11},sNarr:'Você localiza uma passagem lateral com ventilação natural. O ar limpo permite uma rota segura ao redor da nuvem.',fNarr:'A corrente que você seguiu era a fonte do gás! O ar fica pior. Você recua tossindo e busca outro caminho.',fDmg:3},]},],swamp:[{icon:'',title:'Emboscada Rastejante',narr:'A água escura se agita em ondas suaves. Bolhas sobem à superfície, e por um instante você vê escamas brilhantes sob a lama. Algo grande se move abaixo.',choices:[{i:'',t:'Observar e contornar',k:{s:'wis',dc:12},sNarr:'Seus olhos identificam o formato do predador na água. Você traça uma rota elevada, longe de suas mandíbulas.',fNarr:'O predador é mais rápido do que parecia! Mandíbulas emergem da água. Você escapa, mas garras rasgam sua perna.',fDmg:5},{i:'',t:'Criar distração',k:{s:'int',dc:11},sNarr:'Você arremessa um galho pesado na água a dez metros dali. A criatura persegue o ruído, abrindo passagem.',fNarr:'A criatura não cai na armadilha — é mais esperta do que parece. Ignora o galho e avança em sua direção.',fDmg:4},{i:'',t:'Atravessar correndo',k:{s:'dex',dc:13},sNarr:'Seus pés encontram os pontos firmes na lama e você cruza antes que a criatura possa reagir. Velocidade pura.',fNarr:'A lama suga seus pés no pior momento! A criatura ganha terreno e suas garras alcançam suas pernas.',fDmg:6},]},{icon:'',title:'Bruma Desorientante',narr:'Névoa espessa desce sobre o pântano como um manto vivo, engolindo toda visibilidade. A trilha desaparece, as estacas de marcação somem, e até o som parece abafado.',choices:[{i:'',t:'Orientar-se pelas estrelas',k:{s:'wis',dc:11},sNarr:'Olhando para cima, você encontra a Estrela do Norte. Seu senso de direção se mantém firme, e a névoa se dissipa.',fNarr:'As nuvens cobrem tudo e a névoa engana seus sentidos. Você vaga por horas até achar a trilha, exausto.',fDmg:3},{i:'',t:'Seguir os sons da cidade',k:{s:'wis',dc:12},sNarr:'Você fecha os olhos e aguça os ouvidos. Ali — um sino distante, um cão ladrando. Sons que guiam seus passos.',fNarr:'O eco do pântano distorce tudo. Você segue miragens sonoras e anda em círculos até a exaustão.',fDmg:3},]},],mountain:[{icon:'',title:'Passagem Estreita',narr:'A trilha se reduz a uma beirada de menos de um passo. De um lado, rocha vertical. Do outro, precipício que some nas nuvens. O vento empurra você para a borda.',choices:[{i:'',t:'Escalar devagar',k:{s:'dex',dc:13},sNarr:'Dedos e pés encontram apoio na rocha. Centímetro por centímetro, você cruza com precisão de escalador.',fNarr:'Uma rajada de vento na hora errada! Você escorrega e bate o corpo contra a rocha áspera. O precipício quase vence.',fDmg:6},{i:'',t:'Agarrar-se e avançar',k:{s:'str',dc:12},sNarr:'Mãos firmes como garras na rocha, você avança sem olhar para baixo. A força bruta vence a vertigem.',fNarr:'Seus dedos cedem na rocha lisa! A queda é curta — uma saliência abaixo amortece — mas o impacto é brutal.',fDmg:5},{i:'',t:'Procurar rota alternativa',k:{s:'int',dc:11},sNarr:'Você estuda a formação rochosa e descobre um desvio mais largo. Mais longo, porém infinitamente mais seguro.',fNarr:'O desvio leva a um beco sem saída — rocha intransponível. Você perde tempo e volta cansado para a passagem.',fDmg:2},]},{icon:'',title:'Gelo na Trilha',narr:'Gelo traiçoeiro cobre a trilha íngreme, transformando cada passo em uma aposta contra a gravidade. O vento gelado ameaça roubar seu equilíbrio.',choices:[{i:'',t:'Pisar com cuidado',k:{s:'dex',dc:12},sNarr:'Testando cada passo, você encontra as fissuras no gelo que oferecem tração. Lento, mas seguro.',fNarr:'Seus pés perdem tração na parte mais íngreme! Você desliza descontrolado e bate nas pedras abaixo.',fDmg:4},{i:'',t:'Cavar apoios no gelo',k:{s:'str',dc:11},sNarr:'Com força e persistência, você escava degraus no gelo. Uma escada improvisada, mas funcional.',fNarr:'O gelo racha em linha longa sob o impacto! A superfície cede e você desliza junto com os pedaços.',fDmg:5},]},],desert:[{icon:'',title:'Ninho de Escorpiões',narr:'A areia ganha vida ao redor de seus pés! Dezenas de escorpiões emergem das tocas, pinças erguidas e ferrões curvados brilhando ao sol. Você está no centro do ninho.',choices:[{i:'',t:'Saltar para fora',k:{s:'dex',dc:12},sNarr:'Com movimentos explosivos, você salta por cima das criaturas e aterrissa em areia limpa.',fNarr:'Um escorpião maior emerge onde você ia pousar! Uma ferroada no tornozelo — o veneno arde como fogo líquido.',fDmg:5},{i:'',t:'Ficar imóvel',k:{s:'wis',dc:11},sNarr:'Você congela como estátua. Sem movimento ou calor, os escorpiões perdem interesse e retornam às tocas.',fNarr:'Um escorpião escalando sua perna é demais! O pânico toma conta e o ferrão encontra pele exposta.',fDmg:4},]},{icon:'',title:'Exaustão pelo Calor',narr:'O sol é implacável. O ar tremula sobre a areia escaldante, sua boca está seca como pergaminho e a visão escurece nas bordas. Cada passo fica mais pesado.',choices:[{i:'',t:'Resistir e avançar',k:{s:'cn',dc:11},sNarr:'Você controla a respiração, modera o ritmo e conserva energia. Passo firme após passo firme, vence o trecho.',fNarr:'O calor vence a vontade. Suas pernas cedem e você cambaleia — quase desmaia antes de encontrar sombra.',fDmg:3},{i:'',t:'Improvisar proteção',k:{s:'int',dc:10},sNarr:'Com pano úmido na cabeça e pausas nas raras sombras, você mantém a temperatura controlada.',fNarr:'Sem material adequado e sem sombra, o improviso falha. O sol castiga sem misericórdia.',fDmg:4},]},],snow:[{icon:'',title:'Nevasca',narr:'O céu desaba em uma cortina branca furiosa. Flocos grossos chicoteiam seu rosto e o vento gela até os pensamentos. A visibilidade cai para dois metros — a trilha some.',choices:[{i:'',t:'Resistir ao frio',k:{s:'cn',dc:12},sNarr:'Você se agasalha, cerra os dentes e avança contra a tempestade. Sua vontade é mais forte que o frio.',fNarr:'O frio penetra até os ossos, ultrapassando toda proteção. Seus movimentos ficam lentos e entorpecidos.',fDmg:4},{i:'',t:'Cavar abrigo na neve',k:{s:'str',dc:11},sNarr:'Você escava uma trincheira na neve compacta. Seu abrigo bloqueia o vento e conserva o calor. A nevasca passa.',fNarr:'O abrigo desaba sob o peso da neve! Você fica soterrado por segundos aterrorizantes, gelado e machucado.',fDmg:5},]},{icon:'',title:'Lago Congelado',narr:'A trilha cruza um lago congelado sem caminho ao redor. O gelo geme e rachaduras se espalham como veias sob a superfície. Água negra se move lá embaixo.',choices:[{i:'',t:'Distribuir o peso',k:{s:'dex',dc:13},sNarr:'De bruços, você distribui o peso e desliza sobre o gelo. Cada estalo faz seu coração parar, mas alcança o outro lado.',fNarr:'O gelo racha sob você com um estampido! Água gelada invade até a cintura. O choque térmico é brutal.',fDmg:6},{i:'',t:'Contornar pela margem',k:{s:'wis',dc:11},sNarr:'Nas bordas, pedras se projetam sobre o lago. Pulando de rocha em rocha, cruza sem tocar o gelo.',fNarr:'A margem é tão frágil quanto o centro. Uma placa de gelo costeiro cede e você afunda na água congelante.',fDmg:4},]},],volcanic:[{icon:'',title:'Fissura de Lava',narr:'O chão racha diante de seus pés com um estampido! Uma fissura se abre revelando lava incandescente metros abaixo. O calor é insuportável e a rachadura está se alargando.',choices:[{i:'',t:'Saltar sobre a fissura',k:{s:'dex',dc:13},sNarr:'Com um salto potente, você cruza a fissura antes que ela se alargue. Seus pés aterrissam firmes do outro lado.',fNarr:'A fissura era mais larga do que parecia! Você quase não alcança a borda, raspando as pernas na rocha incandescente.',fDmg:6},{i:'',t:'Contornar pelas rochas',k:{s:'wis',dc:11},sNarr:'Seus olhos identificam rochas estáveis que formam um desvio natural. O caminho é mais longo, mas seguro.',fNarr:'As rochas que pareciam estáveis cedem sob o calor! Você pisa em falso e o vapor queima seu tornozelo.',fDmg:4},{i:'',t:'Resistir ao calor e cruzar',k:{s:'cn',dc:12},sNarr:'Protegendo o rosto, você atravessa a zona de calor com determinação. Sua pele arde, mas você resiste.',fNarr:'O calor é demais! Suas roupas fumegam e queimaduras marcam seus braços antes de conseguir se afastar.',fDmg:5},]},{icon:'',title:'Chuva de Cinzas',narr:'O vulcão cospe uma coluna de fumaça negra e cinzas começam a cair como neve sombria. A visibilidade cai rapidamente e o ar se torna irrespirável. Pedras incandescentes ricocheteiam ao longe.',choices:[{i:'',t:'Cobrir-se e avançar',k:{s:'cn',dc:12},sNarr:'Com pano sobre o rosto e passos firmes, você atravessa a cortina de cinzas. Seus pulmões ardem, mas resiste.',fNarr:'As cinzas penetram toda proteção improvisada. Tosse violenta e olhos cegados pela fuligem. Tropeços se seguem.',fDmg:4},{i:'',t:'Buscar abrigo rochoso',k:{s:'int',dc:11},sNarr:'Você identifica uma formação rochosa que protege do impacto direto. Abrigado, espera a pior fase passar.',fNarr:'O abrigo que escolheu canaliza as cinzas como uma chaminé! O ar fica pior do que ao ar livre.',fDmg:3},]},],graveyard:[{icon:'',title:'Mãos da Terra',narr:'A terra macia do cemitério se agita ao redor de seus pés! Dedos esqueléticos irrompem do solo, agarrando seus tornozelos. Os mortos não descansam aqui — e não querem que você parta.',choices:[{i:'',t:'Libertar-se à força',k:{s:'str',dc:12},sNarr:'Com um puxão violento, você arranca seus pés das garras mortas. Ossos se quebram e a terra se acalma.',fNarr:'As mãos são mais fortes do que parecem! Unhas de osso rasgam sua pele antes que consiga se libertar.',fDmg:5},{i:'',t:'Invocar fé ou vontade',k:{s:'cha',dc:11},sNarr:'Sua voz firme ecoa entre as lápides. As mãos recuam, como se reconhecessem uma autoridade que não podem desafiar.',fNarr:'Sua voz falha — o medo é mais forte. As garras apertam enquanto você gagueja, e arranhões profundos marcam suas pernas.',fDmg:4},{i:'',t:'Desviar com agilidade',k:{s:'dex',dc:13},sNarr:'Passos rápidos e leves sobre as sepulturas — você dança entre as mãos emergentes como um fantasma.',fNarr:'Uma mão que você não viu agarra seu tornozelo no meio do passo. A queda é pesada sobre lápides afiadas.',fDmg:5},]},{icon:'',title:'Névoa dos Lamentos',narr:'Uma névoa densa e gélida desce sobre o cemitério. Nela, vozes sussurram seu nome, chamando você para mais fundo entre os túmulos. A desorientação é quase instantânea.',choices:[{i:'',t:'Manter a mente firme',k:{s:'wis',dc:12},sNarr:'Você fecha os olhos e recita marcações mentais do caminho. A névoa tenta confundir, mas seu senso de orientação prevalece.',fNarr:'Os sussurros são hipnóticos. Quando percebe, está em um canto desconhecido do cemitério, gelado e exausto.',fDmg:3},{i:'',t:'Correr para fora da névoa',k:{s:'cn',dc:11},sNarr:'Prendendo a respiração, você sprint através da névoa gélida. O frio morde, mas você emerge do outro lado.',fNarr:'O frio sobrenatural drena suas forças. Seus joelhos cedem e você rasteja até sair da névoa, trêmulo e fraco.',fDmg:4},]},],_default:[{icon:'',title:'Armadilha Abandonada',narr:'Folhas secas cobrem algo metálico na trilha. Um brilho de ferro entre o marrom — armadilha de caçadores, esquecida há meses. O mecanismo ainda parece funcional.',choices:[{i:'',t:'Examinar com cuidado',k:{s:'wis',dc:11},sNarr:'Olhos treinados identificam a placa de pressão e os fios. Você marca a armadilha e desvia com precisão.',fNarr:'O mecanismo é mais sofisticado do que parecia! Ao pisar no que achava ser seguro, o ferro morde sua perna.',fDmg:4},{i:'',t:'Pular por cima',k:{s:'dex',dc:12},sNarr:'Um salto limpo e bem calculado leva você além da armadilha. Seus pés aterrissam em solo limpo e seguro.',fNarr:'Você aterrissa mal e ativa uma segunda armadilha que não havia visto! Impacto duplo — queda e ferro.',fDmg:3},]},{icon:'',title:'Escuridão Repentina',narr:'Nuvens espessas cobrem a lua e as estrelas de uma vez. Escuridão total desce sobre a trilha — você não enxerga nem as próprias mãos. A trilha está ali, em algum lugar.',choices:[{i:'',t:'Seguir pelos sons',k:{s:'wis',dc:10},sNarr:'Aguçando os ouvidos, você percebe o farfalhar de folhas, água corrente — um mapa sonoro que compensa a cegueira.',fNarr:'Sons enganam no escuro. O que parecia trilha firme era encosta. Você rola antes de conseguir se agarrar.',fDmg:3},{i:'',t:'Improvisar luz',k:{s:'int',dc:11},sNarr:'Com galhos secos e engenho, uma tocha improvisada ilumina o caminho. A trilha reaparece, clara e segura.',fNarr:'Sem material seco ou ignição, a escuridão prevalece. O terreno irregular cobra seu preço em tombos.',fDmg:2},]},],};function _getReturnBiome(){return(S.biome||'forest').replace(/^dungeon_/,'');}
function _pickFrom(pool){return pool[Math.floor(Math.random()*pool.length)];}
function _getReturnNarration(){const b=_getReturnBiome();const pool=RETURN_NARRATIONS[b]||RETURN_NARRATIONS._default;return _pickFrom(pool);}
function _getReturnHazard(){const b=_getReturnBiome();const pool=RETURN_HAZARDS[b]||RETURN_HAZARDS._default;return _pickFrom(pool);}
function _getReturnDice(){const canvas=document.getElementById('return-dice-canvas');const particles=document.getElementById('return-dice-particles');if(!canvas)return null;if(_returnDice){_returnDice.dispose();_returnDice=null;}
try{_returnDice=new Dice3D(canvas,{size:160,particlesContainer:particles});}catch(e){console.warn('[EXPLORE] Return dice init failed:',e);return null;}
return _returnDice;}
function _disposeReturnDice(){if(_returnDice){_returnDice.dispose();_returnDice=null;}}
function _renderReturnHP(el){const hp=getCurrentHP();const max=getMaxHP();const pct=(hp/max)*100;const color=pct>60?'#4a8':pct>25?'#dca028':'#c44';el.innerHTML=`<span>HP</span>`+`<div class="exit-hp-bar"><div class="exit-hp-fill" style="transform:scaleX(${Math.max(0.02, pct/100)});background:${color}"></div></div>`+`<span>${hp}/${max}</span>`;}
function _renderReturnProgress(el,j){const pct=Math.round(((j.currentStep-1)/j.totalSteps)*100);let dots='';for(let i=1;i<=j.totalSteps;i++){const cls=i<j.currentStep?'done':i===j.currentStep?'current':'pending';dots+=`<div class="return-progress-dot ${cls}"></div>`;}
el.innerHTML=`<div class="return-progress-bar"><div class="return-progress-fill" style="width:${pct}%"></div></div>`+
(j.totalSteps<=8?`<div class="return-progress-steps">${dots}</div>`:'')+`<div class="return-progress-label"><span>Etapa ${j.currentStep} de ${j.totalSteps}</span></div>`;}
function _addReturnBtn(container,icon,title,desc,descColor,onClick){const btn=document.createElement('button');btn.className='exit-option-btn';btn.innerHTML=`<span class="exit-option-icon">${icon}</span>`+`<div class="exit-option-info"><div class="exit-option-title">${title}</div>`+`<div class="exit-option-desc" style="color:${descColor}">${desc}</div></div>`;btn.addEventListener('click',onClick);container.appendChild(btn);}
function attemptReturnToCity(riskChance){const distance=bfsDistanceToExit(S.playerCol,S.playerRow);const steps=Math.max(1,distance);_returnJourney={totalSteps:steps,currentStep:0,riskChance:riskChance,usedNarrations:new Set(),usedHazards:new Set(),};_returningToCity=true;showReturnJourneyStep();}
function showReturnJourneyStep(){if(!_returnJourney)return;const j=_returnJourney;j.currentStep++;if(j.currentStep>j.totalSteps){_showArrivalScreen();return;}
if(typeof playTravelAnimation==='function'&&j.currentStep>1){const biome=S.biome||'forest';const remaining=j.totalSteps-j.currentStep+1;playTravelAnimation(biome,'',function(){_renderReturnStep();},{duration:2000});return;}
_renderReturnStep();}
function _renderReturnStep(){const j=_returnJourney;if(!j)return;const roll=Math.random()*100;const hasEncounter=roll<j.riskChance*0.5&&S.randomEncounters.length>0;const hasHazard=!hasEncounter&&roll<j.riskChance;const hazard=hasHazard?_getReturnHazard():null;const overlay=document.getElementById('return-journey-overlay');const hpEl=document.getElementById('return-journey-hp');const progressEl=document.getElementById('return-journey-progress');const narrEl=document.getElementById('return-journey-narration');const diceEl=document.getElementById('return-journey-dice');const checkEl=document.getElementById('return-journey-check');const actionsEl=document.getElementById('return-journey-actions');const subtitleEl=document.getElementById('return-journey-subtitle');const iconEl=document.getElementById('return-journey-icon');const titleEl=document.getElementById('return-journey-title');diceEl.classList.remove('active');checkEl.innerHTML='';actionsEl.innerHTML='';_disposeReturnDice();const remaining=j.totalSteps-j.currentStep;titleEl.textContent='Rumo a Eldoria';subtitleEl.textContent=remaining>0?`${remaining + 1} etapa${remaining > 0 ? 's' : ''} restante${remaining > 0 ? 's' : ''}`:'Quase lá...';iconEl.textContent='';_renderReturnHP(hpEl);_renderReturnProgress(progressEl,j);if(hasEncounter){narrEl.innerHTML=`<div class="return-step-badge danger">Encontro na estrada!</div>`+`<div>Sombras se movem entre a vegetação. Algo se aproxima rapidamente...</div>`;_addReturnBtn(actionsEl,'','Enfrentar','Resolver o encontro para continuar','#c44',()=>{overlay.classList.remove('active');const enc=S.randomEncounters.shift();setTimeout(()=>showRandomEncounter(enc),300);});}else if(hasHazard){narrEl.innerHTML=`<div class="return-step-badge hazard">${hazard.title}</div>`+`<div>${hazard.narr}</div>`;for(const choice of hazard.choices){const statName=STAT_NAMES[choice.k.s]||choice.k.s;const mod=getAbilityMod(choice.k.s);const proficient=S.charData&&S.charData.sp&&S.charData.sp.includes(choice.k.s);const profMark=proficient?' ★':'';const chance=Math.max(5,Math.min(95,Math.round(((21-choice.k.dc+mod)/20)*100)));_addReturnBtn(actionsEl,choice.i,choice.t,`${statName}${profMark} DC ${choice.k.dc} | ${mod >= 0 ? '+' : ''}${mod} | ${chance}%`,'#dca028',()=>_rollReturnHazard(hazard,choice));}}else{const biomeLabels={forest:'Floresta',plains:'Planície',cave:'Caverna',swamp:'Pântano',mountain:'Montanha',desert:'Deserto',snow:'Neve'};const biomeLabel=biomeLabels[_getReturnBiome()]||'Estrada';narrEl.innerHTML=`<div class="return-step-badge safe">✓ ${biomeLabel} — Caminho seguro</div>`+`<div>${_getReturnNarration()}</div>`;_addReturnActions(actionsEl,overlay,remaining);}
overlay.classList.add('active');if(window.vHaptic)vHaptic.impact(hasEncounter?'heavy':hasHazard?'medium':'light');}
function _rollReturnHazard(hazard,choice){const actionsEl=document.getElementById('return-journey-actions');const diceEl=document.getElementById('return-journey-dice');const checkEl=document.getElementById('return-journey-check');actionsEl.innerHTML='';const stat=choice.k.s;const dc=choice.k.dc;const mod=getAbilityMod(stat);const mode=getRollMode({s:stat});const{roll,r1,r2}=rollD20(mode);const total=roll+mod;const success=total>=dc;S.checksPerformed.push({stat,dc,roll,mod,ok:success,mode,context:'return',});const dice=_getReturnDice();if(dice){diceEl.classList.add('active');dice.roll(roll,()=>{_resolveReturnHazard(hazard,choice,roll,mod,total,success,r1,r2,mode);});}else{checkEl.innerHTML='';var _rdie=document.createElement('div');_rdie.className='die kept';_rdie.style.cssText='width:56px;height:56px;font-size:28px;margin:0 auto;border-radius:10px';_rdie.textContent='\ud83c\udfb2';checkEl.appendChild(_rdie);var _rcyc=setInterval(function(){_rdie.textContent=Math.floor(Math.random()*20)+1;},50);setTimeout(function(){clearInterval(_rcyc);_rdie.textContent=roll;_resolveReturnHazard(hazard,choice,roll,mod,total,success,r1,r2,mode);},700);}}
function _resolveReturnHazard(hazard,choice,roll,mod,total,success,r1,r2,mode){const overlay=document.getElementById('return-journey-overlay');const checkEl=document.getElementById('return-journey-check');const narrEl=document.getElementById('return-journey-narration');const actionsEl=document.getElementById('return-journey-actions');const hpEl=document.getElementById('return-journey-hp');const statName=STAT_NAMES[choice.k.s]||choice.k.s;const proficient=S.charData&&S.charData.sp&&S.charData.sp.includes(choice.k.s);const profMark=proficient?'★':'';checkEl.innerHTML=buildFormula(roll,mod,statName,profMark,choice.k.dc,total,r1,r2,mode)+`<div style="margin-top:6px;font-size:15px;font-weight:700;color:${success ? '#4a8' : '#c44'}">${success ? 'Sucesso!' : 'Falha!'}</div>`;if(success){narrEl.innerHTML=`<div class="return-step-badge safe">${hazard.title} — Superado!</div>`+`<div>${choice.sNarr}</div>`;}else{const dmg=choice.fDmg||3;S.hpChange-=dmg;if(S.charData){const newHP=Math.max(0,S.charData.hp+S.hpChange);updateHP(newHP,S.charData.mh);}
_renderReturnHP(hpEl);narrEl.innerHTML=`<div class="return-step-badge danger">${hazard.title} — Falha!</div>`+`<div>${choice.fNarr}</div>`+`<div style="margin-top:6px;color:#c44;font-size:13px">-${dmg} HP</div>`;}
if(window.vHaptic)vHaptic.notify(success?'success':'error');const remaining=_returnJourney?_returnJourney.totalSteps-_returnJourney.currentStep:0;setTimeout(()=>{_disposeReturnDice();document.getElementById('return-journey-dice').classList.remove('active');if(getCurrentHP()<=0){actionsEl.innerHTML='';_addReturnBtn(actionsEl,'','Você sucumbiu...','Seus ferimentos foram fatais','#c44',()=>{overlay.classList.remove('active');_returnJourney=null;_returningToCity=false;showDeathSaves();});return;}
_addReturnActions(actionsEl,overlay,remaining);},1200);}
function _addReturnActions(actionsEl,overlay,remaining){actionsEl.innerHTML='';_addReturnBtn(actionsEl,'',remaining>0?'Continuar Viagem':'Chegar à Cidade',remaining>0?`${remaining} etapa${remaining > 1 ? 's' : ''} restante${remaining > 1 ? 's' : ''}`:'Os portões de Eldoria se erguem à frente!',remaining>0?'#8a7a68':'#4a8',()=>showReturnJourneyStep());const foodItems=getFoodItems();if(foodItems.length>0&&remaining>0&&getHPPercent()<100){const div=document.createElement('div');div.className='return-camp-section';actionsEl.appendChild(div);_addReturnBtn(div,'','Montar Acampamento',`Descanso Curto (1d8+CON) — ${foodItems.length} refeição disponível`,'#4a8',()=>{overlay.classList.remove('active');showCampOverlay();});}
const healItems=getHealingItems();if(healItems.length>0&&getHPPercent()<100){const best=healItems[0];_addReturnBtn(actionsEl,'',`Usar ${best.n} (${best.q}x)`,`Restaura ${best.h} HP`,'#4a8',()=>{useInventoryItemAnimated(best,(heal)=>{showTerrainToast(`+${heal} HP`,'ranger');_renderReturnHP(document.getElementById('return-journey-hp'));_addReturnActions(actionsEl,overlay,remaining);});});}}
function _showArrivalScreen(){const overlay=document.getElementById('return-journey-overlay');const hpEl=document.getElementById('return-journey-hp');const progressEl=document.getElementById('return-journey-progress');const narrEl=document.getElementById('return-journey-narration');const diceEl=document.getElementById('return-journey-dice');const checkEl=document.getElementById('return-journey-check');const actionsEl=document.getElementById('return-journey-actions');const subtitleEl=document.getElementById('return-journey-subtitle');const iconEl=document.getElementById('return-journey-icon');const titleEl=document.getElementById('return-journey-title');diceEl.classList.remove('active');checkEl.innerHTML='';actionsEl.innerHTML='';_disposeReturnDice();iconEl.textContent='';iconEl.style.animation='none';titleEl.textContent='Eldoria';subtitleEl.textContent='Você chegou em segurança';_renderReturnHP(hpEl);const j=_returnJourney;if(j){j.currentStep=j.totalSteps+1;_renderReturnProgress(progressEl,j);}
const ARRIVAL_TEXTS={forest:['As árvores se abrem e os muros de Eldoria surgem banhados pela luz dourada. O aroma da floresta se mistura ao cheiro de fumaça das chaminés. Você sobreviveu.','Pássaros cantam uma despedida enquanto a trilha desemboca na estrada principal. Os portões de Eldoria se erguem à frente, acolhedores.','O verde da floresta cede lugar à pedra dos muros. Guardas acenam ao reconhecê-lo entre as árvores. Enfim, segurança.',],plains:['A estrada de terra se alarga e os portões de Eldoria dominam o horizonte. O vento dos campos sopra uma última vez em suas costas.','Rebanhos pastam ao lado da estrada enquanto os muros da cidade crescem a cada passo. O cheiro de pão fresco chega com a brisa.','A planície infinita termina nos muros familiares. Seus pés encontram calçamento e o alívio se instala. Eldoria, finalmente.',],cave:['A luz do dia cega por um instante ao emergir das profundezas. Os muros de Eldoria brilham à distância como uma promessa cumprida.','O ar livre enche seus pulmões após a escuridão opressiva. Os portões de Eldoria nunca pareceram tão acolhedores.','Seus olhos se adaptam à claridade enquanto a estrada serpenteia até os muros da cidade. O pior ficou nas profundezas.',],swamp:['A lama cede lugar a chão firme e o ar úmido se dissipa. Os muros de Eldoria emergem da bruma como uma fortaleza de esperança.','Você limpa a lama das botas na estrada pavimentada. O pântano fica para trás e a civilização retorna com cada passo.','O cheiro pútrido é substituído por aromas de comida e lareiras. Eldoria acolhe quem sobrevive ao pântano.',],mountain:['A descida termina em terras planas e os muros de Eldoria surgem no vale como um oásis de pedra. O frio da montanha fica para trás.','Seus joelhos agradecem o terreno plano após a longa descida. Os portões da cidade se abrem com um ranger familiar.','O vento gélido dos picos é substituído pela brisa amena do vale. Eldoria espera com tetos aquecidos e comida quente.',],desert:['A areia cede lugar à vegetação e os muros de Eldoria surgem como uma miragem que finalmente é real. Água e sombra, enfim.','O calor diminui com a proximidade dos muros. Guardas oferecem água ao vê-lo emergir das areias. O deserto ficou para trás.','Seus lábios rachados esboçam um sorriso ao ver os portões. O deserto tentou, mas Eldoria venceu.',],snow:['A neve diminui e os muros de Eldoria surgem entre os flocos. O calor das lareiras da cidade pode ser sentido mesmo daqui.','Seus membros entorpecidos pelo frio se aquecem com a visão dos portões. A neve não venceu desta vez.','Pegadas na neve levam até a estrada limpa. Guardas com tochas iluminam a entrada. Você sobreviveu ao inverno.',],volcanic:['O ar limpo substitui o enxofre e os muros de Eldoria surgem além das cinzas. Suas queimaduras pulsam, mas você está vivo.','O tremor da terra cessa ao se afastar do vulcão. Eldoria aguarda, imune ao fogo das profundezas.','O calor infernal fica para trás. O cheiro de comida e a visão dos muros renovam suas forças.',],graveyard:['A névoa do cemitério se dissipa como um sonho ruim. Os muros de Eldoria, sólidos e reais, apagam os sussurros dos mortos.','Corvos ficam para trás enquanto a estrada leva aos portões. A luz das tochas dos guardas afasta as sombras persistentes.','O silêncio dos mortos é substituído pelo burburinho dos vivos. Eldoria pulsa com vida — exatamente o que você precisava.',],_default:['Os portões se abrem diante de você. O som familiar da cidade traz alívio. Você sobreviveu à jornada.','As torres de vigia surgem entre as árvores. Os guardas acenam ao reconhecê-lo. Enfim, segurança.','O cheiro de pão fresco e fumaça de lareiras atinge você antes mesmo de ver os muros. Eldoria, finalmente.',],};const arrivalTexts=ARRIVAL_TEXTS[_getReturnBiome()]||ARRIVAL_TEXTS._default;narrEl.innerHTML=`<div class="return-step-badge arrival">Chegada a Eldoria</div>`+`<div>${_pickFrom(arrivalTexts)}</div>`;_addReturnBtn(actionsEl,'','Entrar na Cidade','Seus pés pisam solo seguro novamente','var(--v-gold, #c4953a)',()=>{_closeReturnJourney();finishExploration('exit');});overlay.classList.add('active');if(window.vHaptic)vHaptic.success();}
function _closeReturnJourney(){const overlay=document.getElementById('return-journey-overlay');if(overlay)overlay.classList.remove('active');_disposeReturnDice();_returnJourney=null;_returningToCity=false;const icon=document.getElementById('return-journey-icon');if(icon)icon.style.animation='';}